def __init__(self, customer_id: str):
    self.customer_id = customer_id
    self._events = []
    self._event_ids = set()
    self._summary = None

@property
def summary(self):
    if self._summary is None:
        self._summary = summarize(self._events)
    return self._summary

@summary.setter
def summary(self, value):
    self._summary = value

def get_history(self):
    """Return a snapshot of this customer's events in processing order.

    The snapshot belongs to the caller, who may modify the list or the
    events in it without affecting the state.
    """
    return copy.deepcopy(self._events)

def has_event(self, event_id: str) -> bool:
    return event_id in self._event_ids

def add(self, event) -> None:
    self._event_ids.add(event.event_id)
    if not self._events or (event.ts, event.seq) >= (self._events[-1].ts, self._events[-1].seq):
        self._events.append(event)
    else:
        bisect.insort(self._events, event, key=_order_key)
    self._summary = None

